// src/lib.rs
use parking_lot::RwLock;
use std::collections::{HashMap, VecDeque};
use std::sync::Arc;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

/// Statistics for cache operations
#[derive(Clone, Debug)]
pub struct CacheStats {
    pub hits: u64,
    pub misses: u64,
    pub evictions: u64,
    pub expirations: u64,
    pub size: usize,
    pub memory: usize,
}

/// Eviction reason
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EvictionReason {
    Expired,
    Lru,
    Memory,
}

impl std::fmt::Display for EvictionReason {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            EvictionReason::Expired => write!(f, "expired"),
            EvictionReason::Lru => write!(f, "lru"),
            EvictionReason::Memory => write!(f, "memory"),
        }
    }
}

/// Individual cache entry
struct CacheEntry<V> {
    value: V,
    expires_at: u64,
    size: usize,
    last_accessed: u64,
    access_count: u64,
}

/// Cache configuration
pub struct CacheConfig {
    pub max_entries: usize,
    pub default_ttl_ms: u64,
    pub max_memory_bytes: usize,
    pub eviction_check_interval_ms: u64,
}

impl Default for CacheConfig {
    fn default() -> Self {
        CacheConfig {
            max_entries: 1000,
            default_ttl_ms: 60000,
            max_memory_bytes: 100 * 1024 * 1024,
            eviction_check_interval_ms: 5000,
        }
    }
}

/// Callback type for eviction events
pub type EvictionCallback = Arc<dyn Fn(&str, EvictionReason) + Send + Sync>;

/// LRU Cache with TTL support
pub struct LRUCache<V> {
    entries: Arc<RwLock<HashMap<String, CacheEntry<V>>>>,
    access_order: Arc<RwLock<VecDeque<String>>>,
    config: CacheConfig,
    current_memory: Arc<RwLock<usize>>,
    stats: Arc<RwLock<CacheStats>>,
    eviction_callback: Option<EvictionCallback>,
    eviction_handle: Arc<RwLock<Option<tokio::task::JoinHandle<()>>>>,
}

impl<V: Send + Sync + 'static> LRUCache<V> {
    /// Create a new LRU cache with the given configuration
    pub fn new(config: CacheConfig) -> Self {
        LRUCache {
            entries: Arc::new(RwLock::new(HashMap::new())),
            access_order: Arc::new(RwLock::new(VecDeque::new())),
            config,
            current_memory: Arc::new(RwLock::new(0)),
            stats: Arc::new(RwLock::new(CacheStats {
                hits: 0,
                misses: 0,
                evictions: 0,
                expirations: 0,
                size: 0,
                memory: 0,
            })),
            eviction_callback: None,
            eviction_handle: Arc::new(RwLock::new(None)),
        }
    }

    /// Create a new LRU cache with default configuration
    pub fn new_default() -> Self {
        Self::new(CacheConfig::default())
    }

    /// Create a new LRU cache with callback
    pub fn with_callback(config: CacheConfig, callback: EvictionCallback) -> Self {
        LRUCache {
            entries: Arc::new(RwLock::new(HashMap::new())),
            access_order: Arc::new(RwLock::new(VecDeque::new())),
            config,
            current_memory: Arc::new(RwLock::new(0)),
            stats: Arc::new(RwLock::new(CacheStats {
                hits: 0,
                misses: 0,
                evictions: 0,
                expirations: 0,
                size: 0,
                memory: 0,
            })),
            eviction_callback: Some(callback),
            eviction_handle: Arc::new(RwLock::new(None)),
        }
    }

    /// Get a value from the cache
    pub fn get(&self, key: &str) -> Option<Arc<V>> {
        let mut entries = self.entries.write();
        let entry = entries.get(key)?;

        let now = current_time_ms();
        if now > entry.expires_at {
            drop(entries);
            self.delete_internal(key, EvictionReason::Expired);
            self.stats.write().misses += 1;
            return None;
        }

        let entry = entries.get_mut(key).unwrap();
        entry.last_accessed = now;
        entry.access_count += 1;

        drop(entries);
        self.move_to_front(key);
        self.stats.write().hits += 1;

        // Safe to clone the Arc here, not the actual value
        let entries = self.entries.read();
        Some(Arc::new(unsafe { std::ptr::read(&entries[key].value) }))
    }

    /// Put a value in the cache
    pub fn put(&self, key: impl Into<String>, value: V, ttl_ms: Option<u64>) {
        let key = key.into();
        let size = estimate_size::<V>();
        let ttl = ttl_ms.unwrap_or(self.config.default_ttl_ms);

        let mut entries = self.entries.write();
        let mut memory = self.current_memory.write();

        // Remove old entry if it exists
        if let Some(old_entry) = entries.remove(&key) {
            *memory -= old_entry.size;
            let mut order = self.access_order.write();
            order.retain(|k| k != &key);
            drop(order);
        }

        drop(entries);
        drop(memory);

        // Evict based on memory
        while *self.current_memory.read() + size > self.config.max_memory_bytes {
            if !self.evict_lru(EvictionReason::Memory) {
                break;
            }
        }

        // Evict based on entry count
        while self.entries.read().len() >= self.config.max_entries {
            if !self.evict_lru(EvictionReason::Lru) {
                break;
            }
        }

        let now = current_time_ms();
        let entry = CacheEntry {
            value,
            expires_at: now + ttl,
            size,
            last_accessed: now,
            access_count: 0,
        };

        let mut entries = self.entries.write();
        entries.insert(key.clone(), entry);
        *self.current_memory.write() += size;
        drop(entries);

        self.move_to_front(&key);
    }

    /// Check if a key exists and hasn't expired
    pub fn has(&self, key: &str) -> bool {
        let entries = self.entries.read();
        match entries.get(key) {
            None => false,
            Some(entry) => {
                let now = current_time_ms();
                if now > entry.expires_at {
                    drop(entries);
                    self.delete_internal(key, EvictionReason::Expired);
                    false
                } else {
                    true
                }
            }
        }
    }

    /// Delete a key from the cache
    pub fn delete(&self, key: &str) -> bool {
        self.delete_internal(key, EvictionReason::Lru)
    }

    /// Get current number of entries
    pub fn size(&self) -> usize {
        self.entries.read().len()
    }

    /// Get current memory usage
    pub fn memory_usage(&self) -> usize {
        *self.current_memory.read()
    }

    /// Get cache statistics
    pub fn get_stats(&self) -> CacheStats {
        let mut stats = self.stats.read().clone();
        stats.size = self.entries.read().len();
        stats.memory = *self.current_memory.read();
        stats
    }

    /// Clear all entries from the cache
    pub fn clear(&self) {
        let keys: Vec<_> = self.entries.read().keys().cloned().collect();
        for key in keys {
            self.delete_internal(&key, EvictionReason::Lru);
        }
    }

    /// Start the background eviction loop
    pub fn start_eviction_loop(&self) {
        let mut handle = self.eviction_handle.write();
        if handle.is_some() {
            return; // Already running
        }

        let entries = Arc::clone(&self.entries);
        let access_order = Arc::clone(&self.access_order);
        let current_memory = Arc::clone(&self.current_memory);
        let stats = Arc::clone(&self.stats);
        let interval = self.config.eviction_check_interval_ms;
        let callback = self.eviction_callback.clone();

        let task = tokio::spawn(async move {
            let mut interval = tokio::time::interval(Duration::from_millis(interval));
            loop {
                interval.tick().await;

                let now = current_time_ms();
                let expired_keys: Vec<String> = entries
                    .read()
                    .iter()
                    .filter(|(_, entry)| now > entry.expires_at)
                    .map(|(k, _)| k.clone())
                    .collect();

                for key in expired_keys {
                    entries.write().remove(&key);
                    if let Some(entry) = entries.read().get(&key) {
                        *current_memory.write() -= entry.size;
                    }
                    access_order.write().retain(|k| k != &key);

                    stats.write().expirations += 1;
                    if let Some(cb) = &callback {
                        cb(&key, EvictionReason::Expired);
                    }
                }
            }
        });

        *handle = Some(task);
    }

    /// Stop the background eviction loop
    pub async fn stop_eviction_loop(&self) {
        let mut handle = self.eviction_handle.write();
        if let Some(task) = handle.take() {
            task.abort();
        }
    }

    /// Get all keys in access order
    pub fn keys(&self) -> Vec<String> {
        self.access_order.read().iter().cloned().collect()
    }

    /// Get all values
    pub fn values(&self) -> Vec<Arc<V>> {
        let entries = self.entries.read();
        self.access_order
            .read()
            .iter()
            .filter_map(|k| entries.get(k).map(|e| Arc::new(unsafe { std::ptr::read(&e.value) })))
            .collect()
    }

    // Private helpers
    fn move_to_front(&self, key: &str) {
        let mut order = self.access_order.write();
        order.retain(|k| k != key);
        order.push_front(key.to_string());
    }

    fn evict_lru(&self, reason: EvictionReason) -> bool {
        let mut order = self.access_order.write();
        if let Some(oldest) = order.pop_back() {
            drop(order);
            self.delete_internal(&oldest, reason);
            true
        } else {
            false
        }
    }

    fn delete_internal(&self, key: &str, reason: EvictionReason) -> bool {
        let entry = self.entries.write().remove(key);
        if let Some(entry) = entry {
            *self.current_memory.write() -= entry.size;
            self.access_order.write().retain(|k| k != key);

            match reason {
                EvictionReason::Expired => {
                    self.stats.write().expirations += 1;
                }
                _ => {
                    self.stats.write().evictions += 1;
                }
            }

            if let Some(callback) = &self.eviction_callback {
                callback(key, reason);
            }

            true
        } else {
            false
        }
    }
}

fn current_time_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_millis() as u64
}

fn estimate_size<V>() -> usize {
    std::mem::size_of::<V>().max(64)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_get_put() {
        let cache = LRUCache::new(CacheConfig::default());
        cache.put("a", "hello".to_string(), None);
        assert_eq!(cache.get("a"), Some(Arc::new("hello".to_string())));
        assert_eq!(cache.size(), 1);
    }

    #[test]
    fn test_lru_eviction() {
        let config = CacheConfig {
            max_entries: 3,
            ..Default::default()
        };
        let cache = LRUCache::new(config);

        cache.put("a", "hello".to_string(), None);
        cache.put("b", "world".to_string(), None);
        cache.put("c", "foo".to_string(), None);
        cache.put("d", "bar".to_string(), None);

        assert!(!cache.has("a"));
        assert!(cache.has("d"));
    }

    #[test]
    fn test_access_order() {
        let config = CacheConfig {
            max_entries: 3,
            ..Default::default()
        };
        let cache = LRUCache::new(config);

        cache.put("1", "one".to_string(), None);
        cache.put("2", "two".to_string(), None);
        cache.put("3", "three".to_string(), None);

        cache.get("1");
        cache.put("4", "four".to_string(), None);

        assert!(!cache.has("2"));
        assert!(cache.has("1"));
    }

    #[test]
    fn test_has_nonexistent() {
        let cache = LRUCache::new(CacheConfig::default());
        assert!(!cache.has("nonexistent"));
    }

    #[test]
    fn test_delete() {
        let cache = LRUCache::new(CacheConfig::default());
        cache.put("a", "hello".to_string(), None);
        assert!(cache.delete("a"));
        assert!(!cache.has("a"));
    }

    #[test]
    fn test_clear() {
        let cache = LRUCache::new(CacheConfig::default());
        cache.put("a", "hello".to_string(), None);
        cache.put("b", "world".to_string(), None);
        cache.clear();
        assert_eq!(cache.size(), 0);
    }

    #[test]
    fn test_stats() {
        let cache = LRUCache::new(CacheConfig::default());
        cache.put("a", "hello".to_string(), None);
        cache.get("a");
        cache.get("a");
        cache.get("nonexistent");

        let stats = cache.get_stats();
        assert_eq!(stats.hits, 2);
        assert_eq!(stats.misses, 1);
    }

    #[test]
    fn test_memory_limit() {
        let config = CacheConfig {
            max_entries: 100,
            max_memory_bytes: 100,
            ..Default::default()
        };
        let cache = LRUCache::new(config);

        cache.put("1", "x".to_string(), None);
        cache.put("2", "y".to_string(), None);
        cache.put("3", "z".to_string(), None);

        assert!(cache.memory_usage() <= 200); // Rough check (size_of + string overhead)
    }

    #[test]
    fn test_callback() {
        let evicted = Arc::new(RwLock::new(Vec::new()));
        let evicted_clone = Arc::clone(&evicted);

        let callback = Arc::new(move |key: &str, reason: EvictionReason| {
            evicted_clone.write().push((key.to_string(), reason));
        });

        let config = CacheConfig {
            max_entries: 2,
            ..Default::default()
        };
        let cache = LRUCache::with_callback(config, callback);

        cache.put("a", "hello".to_string(), None);
        cache.put("b", "world".to_string(), None);
        cache.put("c", "foo".to_string(), None);

        let evicted_list = evicted.read();
        assert_eq!(evicted_list.len(), 1);
        assert_eq!(evicted_list[0].0, "a");
        assert_eq!(evicted_list[0].1, EvictionReason::Lru);
    }

    #[test]
    fn test_keys() {
        let cache = LRUCache::new(CacheConfig::default());
        cache.put("a", "hello".to_string(), None);
        cache.put("b", "world".to_string(), None);

        let keys = cache.keys();
        assert_eq!(keys.len(), 2);
        assert!(keys.contains(&"a".to_string()));
        assert!(keys.contains(&"b".to_string()));
    }

    #[tokio::test]
    async fn test_ttl_expiration() {
        let config = CacheConfig {
            default_ttl_ms: 50,
            ..Default::default()
        };
        let cache = LRUCache::new(config);

        cache.put("x", "temp".to_string(), Some(50));
        assert!(cache.has("x"));

        tokio::time::sleep(Duration::from_millis(80)).await;
        assert!(!cache.has("x"));
    }

    #[tokio::test]
    async fn test_eviction_loop() {
        let config = CacheConfig {
            default_ttl_ms: 50,
            eviction_check_interval_ms: 30,
            ..Default::default()
        };
        let cache = LRUCache::new(config);

        cache.put("e1", "val1".to_string(), Some(50));
        cache.start_eviction_loop();

        tokio::time::sleep(Duration::from_millis(150)).await;

        assert!(!cache.has("e1"));
        cache.stop_eviction_loop().await;
    }

    #[test]
    fn test_update_existing() {
        let cache = LRUCache::new(CacheConfig::default());
        cache.put("a", "hello".to_string(), None);
        cache.put("a", "world".to_string(), None);

        assert_eq!(cache.get("a"), Some(Arc::new("world".to_string())));
        assert_eq!(cache.size(), 1);
    }
}
