    // Test 6: Eviction loop with TTL
    println!("Test 6: Eviction loop with TTL");
    let cache4 = LRUCache::new(CacheConfig {
        default_ttl_ms: 100,
        eviction_check_interval_ms: 30,
        ..Default::default()
    });
    cache4.put("e1", "val1".to_string(), Some(50));
    cache4.start_eviction_loop();
    tokio::time::sleep(Duration::from_millis(150)).await;
    assert!(!cache4.has("e1"));
    cache4.stop_eviction_loop().await;
    println!("✓ Eviction loop works\n");

    // Test 7: Callback on eviction
    println!("Test 7: Eviction callback");
    let evicted = Arc::new(parking_lot::RwLock::new(Vec::new()));
    let evicted_clone = Arc::clone(&evicted);

    let callback = Arc::new(move |key: &str, reason: EvictionReason| {
        evicted_clone
            .write()
            .push((key.to_string(), reason));
    });

    let cache5 = LRUCache::with_callback(
        CacheConfig {
            max_entries: 2,
            ..Default::default()
        },
        callback,
    );

    cache5.put("x", "val1".to_string(), None);
    cache5.put("y", "val2".to_string(), None);
    cache5.put("z", "val3".to_string(), None); // should trigger eviction callback

    let evicted_list = evicted.read();
    assert!(!evicted_list.is_empty());
    println!(
        "✓ Eviction callback triggered: {:?}",
        evicted_list[0]
    );
    println!();

    // Test 8: Keys and values
    println!("Test 8: Keys and values");
